const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Mahajanga location
  const mahajanga = ee.Geometry.Point([46.31, -15.62]);
  const bufferZone = mahajanga.buffer(50000); // 50 km buffer for city area

  // 2. Define January 2020 time period
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 3. Load CHIRPS precipitation data
  let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(bufferZone);

  const imgCount = col.size().getInfo();
  console.log('CHIRPS Images found (Jan 2020): ' + imgCount);

  if (imgCount === 0) {
    console.log('No precipitation data available for Mahajanga in January 2020.');
    console.log('C1');
    return;
  }

  // 4. Sum daily precipitation to get total monthly rainfall
  const monthlyRainfall = col.select('precipitation').sum();

  // 5. Calculate mean rainfall over the city area (in mm)
  const stats = monthlyRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const rainfallMm = stats['precipitation'];

  console.log('Raw value check: ' + rainfallMm);

  if (rainfallMm === null || rainfallMm === undefined || isNaN(rainfallMm)) {
    console.log('Calculation failed or invalid result.');
    console.log('C3');
    return;
  }

  // 6. Validate: Check for unrealistic values
  if (rainfallMm < 0 || rainfallMm > 2000) {
    console.log('Invalid precipitation value: ' + rainfallMm + ' mm');
    console.log('C3');
    return;
  }

  // 7. Pixel count validation
  const pixelCount = monthlyRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bufferZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCount['precipitation'] || 0;
  console.log('Valid pixels: ' + validPixels);

  if (validPixels === 0) {
    console.log('No valid precipitation pixels in region.');
    console.log('C2');
    return;
  }

  // 8. Convert to inches and compare
  const rainfallInches = rainfallMm / 25.4;
  const threshold = 12;

  console.log('January 2020 Mahajanga Rainfall: ' + rainfallMm.toFixed(1) + ' mm (' + rainfallInches.toFixed(2) + ' inches)');
  console.log('Threshold: 12 inches (304.8 mm)');
  console.log('Exceeded threshold: ' + (rainfallInches > threshold));

  // 9. Final answer
  if (rainfallInches > threshold) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
